0}.muted{color:var(--muted)}.callout{border-left:4px solid #d59b23;background:#fff9e8;padding:12px 15px;border-radius:0 10px 10px 0;margin-top:13px}.callout.info{border-color:#21868c;background:#effafa}.steps{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.step{border:1px solid var(--line);border-radius:12px;padding:14px;display:flex;gap:12px}.num{flex:0 0 29px;height:29px;border-radius:9px;display:grid;place-items:center;background:#e9f3f4;color:#176b78;font-weight:800}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:9px 10px;border:1px solid var(--line);vertical-align:top}th{background:#f5f8fb;white-space:nowrap}code{font-family:Consolas,monospace;color:#145b72;overflow-wrap:anywhere}.code{background:#101c2d;color:#d8e5f7;border-radius:12px;padding:15px;overflow:auto;font:12px/1.65 Consolas,monospace;white-space:pre}.code code{color:inherit}.footer{color:#718096;text-align:center;font-size:12px;padding-top:10px}@media(max-width:760px){.shell{width:min(100% - 22px,1180px);padding-top:12px}.hero{padding:23px}.layout{grid-template-columns:1fr}.nav{position:static;display:flex;overflow:auto;white-space:nowrap;gap:3px}.nav strong{display:none}.nav a{display:inline-block}.steps{grid-template-columns:1fr}.card{padding:17px}.top a span{display:none}}
